const inp = $input.first().json;
const required = ['admin_whatsapp', 'admin_body'];
const missing = required.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { _error: 'inputs_incompletos', missing } }];
}
return [{
  json: {
    admin_whatsapp: inp.admin_whatsapp,
    admin_body: inp.admin_body,
    p1_json: JSON.stringify({
      admin_whatsapp: inp.admin_whatsapp,
      admin_body: inp.admin_body
    }),
  }
}];

const resp = $input.first().json;
const content = resp.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(content); }
catch (e) { parsed = { intent: 'ruido', modo: 'lectura', respuesta_admin: 'No pude procesar el mensaje. ¿Puedes reformular?' }; }

const upstream = $('Ensamblar prompt admin').first().json;
const admin_body = upstream.admin_body || '';
const accion_pendiente_id = upstream.accion_pendiente_id;

function normalize(s) {
  return (s || '').toLowerCase().trim()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
const norm = normalize(admin_body);

// === Override 1: sí/no cuando hay accion_pendiente ===
if (accion_pendiente_id) {
  const confirma = /^(si|sii+|s$|dale|dale\spues|ok|okay|okey|confirmo|confirmar|ejecuta|ejecutalo|hazlo|hagalo|hagale|adelante|listo|de\sacuerdo|si\sconfirmo)\b/.test(norm);
  const cancela = /^(no|nop|nope|cancela|cancelar|olvidalo|olvidemoslo|dejalo|dejemoslo|negativo|mejor\sno)\b/.test(norm);
  if (confirma) {
    parsed.modo = 'ejecutar';
    parsed.intent = parsed.intent || 'confirmar';
    parsed.respuesta_admin = parsed.respuesta_admin || 'Confirmado, ejecutando.';
  } else if (cancela) {
    parsed.modo = 'cancelar';
    parsed.intent = parsed.intent || 'cancelar';
    parsed.respuesta_admin = parsed.respuesta_admin || 'OK, descarté la acción.';
  }
}

// === Override 2: lectura forzada cuando admin pide info clara ===
// Palabras de lectura inequívocas
const palabrasLectura = /\b(muestr|enseñ|ens[eé]ñ|env[ií]a|lista|listad|listam|ver(?:lo|la|me)?\b|c[oó]mo\s+est|qu[eé]\s+(?:hay|tengo|tienes|cita|bloqueo|tenemos)|cu[aá]l(?:es)?|disponibilidad|consult|info)/i.test(norm);
// Palabras de acción destructiva
const palabrasAccion = /\b(bloquea(?:r|me|los|le|n)?|bloquemos|cancela(?:r|me|la|las|lo|los|n)?|cancelemos|elimina(?:r|los|la|el|n)?|eliminemos|borra(?:r|me|los|n)?|quita(?:r|los|la|el|n)?|cambia(?:r|los|la|le|n)?|cambiemos|muev(?:e|a|an|en)|mover|reset(?:ea(?:r|me|lo|n)?)?|libera(?:r|n)?|abr(?:e|a|an|en)|abrir)\b/i.test(norm);

if (palabrasLectura && !palabrasAccion && parsed.modo !== 'ejecutar' && parsed.modo !== 'cancelar') {
  parsed.modo = 'lectura';
  parsed.accion_pendiente = null;
  // Descartar respuesta_admin si parece preview alucinado
  if (parsed.respuesta_admin && /voy\s+a\s+(eliminar|registrar|cancelar|crear)|confirma|preview/i.test(parsed.respuesta_admin)) {
    parsed.respuesta_admin = null;
  }
  if (!parsed.query) {
    parsed.query = { tipo: 'ayuda', params: {} };
    if (/bloque/i.test(norm)) parsed.query.tipo = 'listar_bloqueos';
    else if (/cita/i.test(norm)) parsed.query.tipo = 'listar_citas';
    else if (/disponibilidad/i.test(norm)) parsed.query.tipo = 'ver_disponibilidad';
    else if (/(?:cliente|histor|info)/i.test(norm)) {
      parsed.query.tipo = 'ver_cliente';
      const phoneMatch = admin_body.match(/\b(\d{10,15})\b/);
      if (phoneMatch) {
        parsed.query.params = { whatsapp: phoneMatch[1] };
      } else {
        const m = admin_body.match(/(?:cliente|info\s+(?:de|del)|historial\s+(?:de|del)|muestram?e?\s+(?:a|al|el cliente)?)\s+([A-ZÁ-Úa-zá-ú][\wÁ-Úá-ú\.\s]*?)(?:\s*[?¿.!]|$)/i);
        if (m) parsed.query.params = { cliente: m[1].trim() };
      }
    }
  }
  // Extraer fecha del mensaje cuando es listar_*
  if (parsed.query && (parsed.query.tipo === 'listar_bloqueos' || parsed.query.tipo === 'listar_citas')) {
    parsed.query.params = parsed.query.params || {};
    const todayBog = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
    const [ty, tm, td] = todayBog.split('-').map(Number);
    let fechaInicio = todayBog;
    let fechaFin = todayBog;
    if (/\bma[nñ]ana\b/i.test(norm)) {
      const tom = new Date(Date.UTC(ty, tm-1, td+1));
      fechaInicio = fechaFin = tom.toISOString().split('T')[0];
    } else if (/\bhoy\b/i.test(norm)) {
      fechaInicio = fechaFin = todayBog;
    } else {
      const proxMatch = norm.match(/proxim[oa]s?\s+(\d+)\s+d[ií]as?/i) || norm.match(/(\d+)\s+d[ií]as?/i);
      if (proxMatch) {
        const days = parseInt(proxMatch[1]);
        const future = new Date(Date.UTC(ty, tm-1, td+days));
        fechaFin = future.toISOString().split('T')[0];
      } else if (/\bsemana\b/i.test(norm)) {
        const week = new Date(Date.UTC(ty, tm-1, td+7));
        fechaFin = week.toISOString().split('T')[0];
      } else {
        const diaMap = {'lun':1,'mart':2,'mierc':3,'juev':4,'vier':5,'sab':6,'domin':0};
        const dm = norm.match(/\b(lun|mart|mierc|juev|vier|sab|domin)/i);
        if (dm) {
          const target = diaMap[dm[1]];
          const todayDow = new Date(Date.UTC(ty, tm-1, td, 12)).getUTCDay();
          const offset = ((target - todayDow + 7) % 7) || 7;
          const next = new Date(Date.UTC(ty, tm-1, td+offset));
          fechaInicio = fechaFin = next.toISOString().split('T')[0];
        }
      }
    }
    if (!parsed.query.params.fecha_desde) parsed.query.params.fecha_desde = `${fechaInicio}T00:00:00-05:00`;
    if (!parsed.query.params.fecha_hasta) parsed.query.params.fecha_hasta = `${fechaFin}T23:59:59-05:00`;
  }
}

// === Validación cruzada bloqueo_id por hora ===
if (parsed.modo === 'preview_confirmacion' && parsed.accion_pendiente?.tipo === 'eliminar_bloqueo') {
  const ctxRaw = $('Cargar contexto admin').first().json;
  const ctx = ctxRaw.ctx || ctxRaw;
  const bloqueos = ctx.bloqueos_vigentes || [];
  const blockId = parsed.accion_pendiente?.params?.bloqueo_id;
  const blockChosen = bloqueos.find(b => b.id === blockId);
  const horaMatch = admin_body.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm|h)?\b/i);
  let horaAdmin24 = null;
  if (horaMatch) {
    let h = parseInt(horaMatch[1]);
    const ampm = (horaMatch[3] || '').toLowerCase();
    if (ampm === 'pm' && h < 12) h += 12;
    if (ampm === 'am' && h === 12) h = 0;
    if (h >= 0 && h <= 23) horaAdmin24 = h;
  }
  if (horaAdmin24 !== null && blockChosen) {
    const horaBlock24 = parseInt(new Date(blockChosen.inicio).toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: 'America/Bogota' }));
    if (horaAdmin24 !== horaBlock24) {
      const candidates = bloqueos.filter(b => parseInt(new Date(b.inicio).toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: 'America/Bogota' })) === horaAdmin24);
      if (candidates.length === 1) {
        const correct = candidates[0];
        parsed.accion_pendiente.params.bloqueo_id = correct.id;
        const fechaStr = new Date(correct.inicio).toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'America/Bogota' });
        parsed.respuesta_admin = `Voy a eliminar el bloqueo de ${correct.terapeuta_nombre} del ${fechaStr} (motivo: ${correct.motivo || 'sin motivo'}). ¿Confirmas?`;
      } else if (candidates.length > 1) {
        parsed.modo = 'lectura';
        parsed.respuesta_admin = `Encontré ${candidates.length} bloqueos a esa hora. ¿Cuál? Dime el terapeuta o el motivo.`;
        parsed.accion_pendiente = null;
      }
    }
  }
}

return [{
  json: {
    modo: parsed.modo || 'lectura',
    intent: parsed.intent || 'ruido',
    respuesta_admin: parsed.respuesta_admin || 'OK.',
    query: parsed.query || null,
    accion_pendiente: parsed.accion_pendiente || null,
    accion_a_ejecutar: parsed.accion_a_ejecutar || null,
    admin_whatsapp: upstream.admin_whatsapp,
    admin_body: upstream.admin_body,
    accion_pendiente_id_existente: accion_pendiente_id,
    intent_overridden: parsed.modo === 'ejecutar' || parsed.modo === 'cancelar',
    _gpt_raw: parsed,
  }
}];

const j = $json;
const out = { ...j };

if (j.modo === 'lectura') {
  const tipo = j.query?.tipo || 'ayuda';
  const params = j.query?.params || {};
  const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });

  if (tipo === 'listar_citas') {
    let desde = params.fecha_desde || `${hoy}T00:00:00-05:00`;
    let hasta = params.fecha_hasta || `${hoy}T23:59:59-05:00`;
    out.sql_query_params = JSON.stringify({ fecha_desde: desde, fecha_hasta: hasta });
    out.sql_action = 'listar_citas';
  } else if (tipo === 'listar_bloqueos' || tipo === 'ver_bloqueos') {
    let desde = params.fecha_desde || `${hoy}T00:00:00-05:00`;
    let hasta = params.fecha_hasta || `${hoy}T23:59:59-05:00`;
    out.sql_query_params = JSON.stringify({ fecha_desde: desde, fecha_hasta: hasta });
    out.sql_action = 'listar_bloqueos';
  } else if (tipo === 'ver_disponibilidad' || tipo === 'consultar_horario' || tipo === 'consultar_disponibilidad') {
    const terapeuta = params.terapeuta || params.terapeuta_nombre || params.nombre || '';
    const fecha = params.fecha || params.dia || hoy;
    out.sql_query_params = JSON.stringify({ terapeuta_buscar: terapeuta, fecha });
    out.sql_action = 'ver_disponibilidad';
  } else if (tipo === 'ver_cliente' || tipo === 'consultar_cliente' || tipo === 'info_cliente') {
    const buscar = (params.cliente || params.nombre || params.whatsapp || params.whatsapp_id || '').toString().trim();
    if (!buscar) {
      out.sql_action = 'sin_query';
      out.respuesta_admin = '🤔 ¿De qué cliente quieres ver la info? Dime el nombre o el WhatsApp.';
    } else {
      out.sql_query_params = JSON.stringify({ buscar });
      out.sql_action = 'ver_cliente';
    }
  } else {
    out.sql_action = 'sin_query';
  }
} else if (j.modo === 'preview_confirmacion') {
  if (!j.accion_pendiente) {
    out.sql_action = 'sin_query';
    out.respuesta_admin = 'No entendí la acción. Reformula por favor.';
  } else {
    out.sql_action = 'preview';
    out.sql_query_params = JSON.stringify({
      admin_whatsapp: j.admin_whatsapp,
      accion: j.accion_pendiente,
      preview_text: j.respuesta_admin
    });
  }
} else if (j.modo === 'ejecutar') {
  out.sql_action = 'ejecutar';
  out.sql_query_params = j.admin_whatsapp;
} else if (j.modo === 'cancelar') {
  out.sql_action = 'cancelar';
  out.sql_query_params = j.admin_whatsapp;
} else {
  out.sql_action = 'sin_query';
}

return [{ json: out }];

const all = $input.all();
const j = $('Rutear y preparar SQL').first().json;
const sqlResults = all.map(item => item.json).filter(x => Object.keys(x).length > 0);

let text = j.respuesta_admin || 'Listo.';
const DIAS = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];

function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function fmtFechaHora(iso) {
  return new Date(iso).toLocaleString('es-CO', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'America/Bogota' });
}
function fmtHora(iso) {
  return new Date(iso).toLocaleString('es-CO', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Bogota' });
}

// Variantes aleatorias
const VAR = {
  citas_vacio: [
    '📅 No tengo citas programadas en ese rango. Si quieres reviso otro día, solo dime.',
    '📅 No hay nada agendado para esos días. ¿Quieres que verifique otra fecha?',
    '🌿 Esa fecha está libre, ninguna cita agendada. Avísame si quieres ver otro rango.',
    '📅 No encuentro citas para ese rango. ¿Te miro otro día?',
  ],
  bloqueos_vacio: [
    '🌿 No tengo bloqueos registrados en ese rango. Todo despejado.',
    '🌿 Esa fecha está libre de bloqueos, todo en orden.',
    '🌿 No hay bloqueos para ese rango. Las terapeutas están disponibles.',
    '✨ Esa fecha está limpia, sin bloqueos registrados.',
  ],
  citas_intro: [
    n => n === 1 ? '🗓️ Tengo 1 cita:' : `🗓️ Tengo ${n} citas:`,
    n => n === 1 ? '🗓️ Encontré 1 cita:' : `🗓️ Encontré ${n} citas:`,
    n => n === 1 ? '📋 Hay 1 cita en ese rango:' : `📋 Hay ${n} citas en ese rango:`,
  ],
  bloqueos_intro: [
    n => n === 1 ? '🚫 Tengo 1 bloqueo:' : `🚫 Tengo ${n} bloqueos:`,
    n => n === 1 ? '🚫 Encontré 1 bloqueo:' : `🚫 Encontré ${n} bloqueos:`,
    n => n === 1 ? '📋 Hay 1 bloqueo:' : `📋 Hay ${n} bloqueos:`,
  ],
  bloqueo_creado: [
    '✅ Listo, bloqueo registrado.',
    '✅ Bloqueo guardado.',
    '✅ Hecho, agregué el bloqueo.',
    '✨ Listo, queda registrado.',
    '✅ Bloqueo agendado, todo bien.',
  ],
  bloqueo_eliminado: [
    '✅ Listo, bloqueo eliminado.',
    '✅ Bloqueo quitado.',
    '✅ Eliminé ese bloqueo.',
    '✨ Listo, ya no está ese bloqueo.',
  ],
  bloqueos_eliminados_n: [
    n => `✅ Listo, eliminé ${n} bloqueos.`,
    n => `✅ Quité ${n} bloqueos.`,
    n => `✨ Hecho, ${n} bloqueos eliminados.`,
  ],
  cita_cancelada: [
    '✅ Listo, cita cancelada.',
    '✅ Cita cancelada.',
    '✅ Hecho, la cita queda cancelada.',
    '✨ Cancelé la cita.',
  ],
  bloqueo_duplicado: [
    '⚠️ Ya tenía un bloqueo idéntico para ese terapeuta y horario, así que no creé un duplicado.',
    '⚠️ Ese bloqueo ya existe para ese terapeuta y horario. No agregué nada nuevo.',
    '⚠️ Ya tengo registrado un bloqueo igual ahí. Lo dejo como está.',
  ],
  no_match_eliminar: [
    '🤔 No encontré un bloqueo que coincida con esos datos. ¿Me confirmas la fecha exacta?',
    '🤔 No tengo un bloqueo así. ¿Verificamos la fecha o el terapeuta?',
    '🤔 No matchea con ningún bloqueo registrado. ¿Me das más detalle?',
  ],
  cancelado_admin: [
    '🌿 Listo, descarté la acción. ¿Algo más?',
    '🌿 OK, lo dejé. ¿En qué más te ayudo?',
    '✨ Cancelado. ¿Necesitas algo más?',
    '🌿 Listo, no se hace nada. ¿Otra cosa?',
  ],
  pending_expirado: [
    '🤔 No encontré la acción pendiente — puede que haya expirado. ¿Repetimos?',
    '🤔 Esa acción ya no está disponible (probablemente expiró). ¿La intentamos de nuevo?',
    '🤔 La confirmación expiró. Si quieres lo volvemos a hacer.',
  ],
  cliente_no_match: [
    '🤔 No encuentro a ese cliente. ¿Me confirmas el nombre o el WhatsApp exacto?',
    '🤔 Ese nombre no me suena. ¿Verificamos los datos?',
    '🤔 No matchea con ningún cliente registrado. ¿Me das más detalle?',
  ],
  terapeuta_no_match: [
    '🤔 No reconocí ese terapeuta. ¿Me confirmas el nombre exacto?',
    '🤔 No encuentro a ese terapeuta. ¿Me das el nombre completo?',
    '🤔 Ese nombre no me suena. ¿Cuál de los terapeutas activos buscas?',
  ],
};

if (j.modo === 'lectura' && j.sql_action === 'listar_citas') {
  if (sqlResults.length === 0) {
    text = pick(VAR.citas_vacio);
  } else {
    const lineas = sqlResults.map(c => `• ${fmtFechaHora(c.inicio_local)} | ${c.servicio} | ${c.terapeuta} | ${c.cliente_nombre || c.whatsapp_id} | ${c.estado}`).join('\n');
    text = `${pick(VAR.citas_intro)(sqlResults.length)}\n\n${lineas}`;
  }
} else if (j.modo === 'lectura' && j.sql_action === 'listar_bloqueos') {
  if (sqlResults.length === 0) {
    text = pick(VAR.bloqueos_vacio);
  } else {
    const lineas = sqlResults.map(b => `• ${fmtFechaHora(b.inicio)}—${fmtHora(b.fin)} | ${b.terapeuta_nombre} | ${b.motivo || 'sin motivo'}`).join('\n');
    text = `${pick(VAR.bloqueos_intro)(sqlResults.length)}\n\n${lineas}`;
  }
} else if (j.modo === 'lectura' && j.sql_action === 'ver_disponibilidad') {
  const r = sqlResults[0] || {};
  if (!r.terapeuta) {
    text = pick(VAR.terapeuta_no_match);
  } else {
    const t = r.terapeuta;
    const [fy, fm, fd] = r.fecha.split('-').map(Number);
    const refUTC = new Date(Date.UTC(fy, fm-1, fd, 12));
    const dia = DIAS[refUTC.getUTCDay()];
    const fechaStr = refUTC.toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'America/Bogota' });
    let horarioStr = 'no trabaja ese día';
    const franjas = (t.horario_base || {})[dia] || [];
    if (franjas.length) horarioStr = franjas.map(f => `${f.inicio}-${f.fin}`).join(', ');
    const citasStr = (r.citas && r.citas.length)
      ? r.citas.map(c => `  • ${fmtHora(c.slot_inicio)}-${fmtHora(c.slot_fin)} ${c.servicio_nombre} (${c.estado})`).join('\n')
      : '  ninguna';
    const bloqStr = (r.bloqueos && r.bloqueos.length)
      ? r.bloqueos.map(b => `  • ${fmtHora(b.inicio)}-${fmtHora(b.fin)} — ${b.motivo || 'sin motivo'}`).join('\n')
      : '  ninguno';
    text = `📅 *${t.nombre}* — ${fechaStr}\n\n🕒 *Horario base:* ${horarioStr}\n\n📋 *Citas:*\n${citasStr}\n\n🚫 *Bloqueos:*\n${bloqStr}`;
  }
} else if (j.modo === 'lectura' && j.sql_action === 'ver_cliente') {
  if (sqlResults.length === 0) {
    text = pick(VAR.cliente_no_match);
  } else if (sqlResults.length > 1) {
    const lineas = sqlResults.map(c => `• ${c.nombre} (${c.whatsapp_id}) — ${c.citas_ejecutadas} citas`).join('\n');
    text = `🤔 Encontré ${sqlResults.length} clientes con ese nombre. ¿Cuál?\n\n${lineas}`;
  } else {
    const c = sqlResults[0];
    const fechaReg = new Date(c.created_at).toLocaleDateString('es-CO', { day:'numeric', month:'short', year:'numeric', timeZone:'America/Bogota' });
    const ultima = c.ultima_visita ? new Date(c.ultima_visita).toLocaleDateString('es-CO', { day:'numeric', month:'short', year:'numeric', timeZone:'America/Bogota' }) : 'sin visitas registradas';
    const gastoStr = c.gasto_total ? `${Number(c.gasto_total).toLocaleString('es-CO')}` : '$0';
    const blockStr = c.bloqueado ? '🚫 *BLOQUEADO*\n' : '';
    let proxStr = '';
    if (c.proxima_cita_detail) {
      const p = c.proxima_cita_detail;
      proxStr = `\n\n📅 *Próxima cita:* ${fmtFechaHora(p.slot)} | ${p.servicio} | ${p.terapeuta} | ${p.sede}`;
    }
    text = `👤 *${c.nombre}* (${c.whatsapp_id})\n${blockStr}_Registrado: ${fechaReg}_\n\n📋 *Citas:* ${c.citas_ejecutadas} ejecutadas, ${c.citas_canceladas} canceladas, ${c.citas_no_show} no-show\n💰 *Gasto total:* ${gastoStr}\n🎯 *Servicio favorito:* ${c.servicio_favorito || '—'}\n🏛️ *Sede favorita:* ${c.sede_favorita || '—'}\n🗓️ *Última visita:* ${ultima}\n\n🔄 *Contadores:* ${c.contador_no_shows} no-shows, ${c.contador_reprogramaciones} reprog actual / ${c.contador_reprog_vitalicio} vitalicio${proxStr}`;
  }
} else if (j.modo === 'preview_confirmacion') {
  text = j.respuesta_admin;
} else if (j.modo === 'ejecutar') {
  const r = sqlResults[0] || {};
  if (!r.tipo) text = pick(VAR.pending_expirado);
  else if (r.cita_cancelada) text = pick(VAR.cita_cancelada);
  else if (r.bloqueo_creado) text = pick(VAR.bloqueo_creado);
  else if (r.tipo === 'crear_bloqueo' && r.bloqueo_duplicado_id) text = pick(VAR.bloqueo_duplicado);
  else if (Number(r.bloqueos_eliminados || 0) > 0) {
    const _n = Number(r.bloqueos_eliminados);
    text = _n === 1 ? pick(VAR.bloqueo_eliminado) : pick(VAR.bloqueos_eliminados_n)(_n);
  }
  else if (['eliminar_bloqueo','desbloquear','quitar_bloqueo'].includes(r.tipo) && (!r.bloqueos_eliminados || r.bloqueos_eliminados === 0)) text = pick(VAR.no_match_eliminar);
  else if (r.cliente_bloqueado) text = `✅ Cliente ${r.cliente_bloqueado} bloqueado.`;
  else if (r.cliente_desbloqueado) text = `✅ Cliente ${r.cliente_desbloqueado} desbloqueado.`;
  else if (r.reset_realizado) text = `✅ Contador de reprogramaciones reseteado para ${r.reset_realizado}.`;
  else text = '✅ Listo, acción ejecutada.';
} else if (j.modo === 'cancelar') {
